def parse_config_value(raw: str) -> int:
    try:
        return int(raw)
    except:
        return -1


def parse_port(raw: str) -> int:
    try:
        port = int(raw)
        if not 1 <= port <= 65535:
            raise ValueError('out of range')
        return port
    except:
        return 8080

